mapper.select:
select
A.REGIST_SEQNO registSeqno,
ifnull(t2.pbc_code,A.PBC_ACCOUNT_ID) PBC_ACCOUNT_ID,
A.MDATE mdate,
A.SEND_STATUS sendStatus,
A.SUBMIT_TIME submitTime,
A.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
A.SUMIT_SEQ sumitSeq,
A.STATUS_DATE statusDate,
A.PBC_SUBMIT_DEADLINE pbcSubmitDeadline,
A.SUBMIT_DEADLINE submitDeadline,
A.STATUS status,
A.CREATE_USER createUser,
A.ORG_CODE orgCode,
A.CREATE_DEPT createDept,
A.CREATE_TIME createTime,
A.UPDATE_USER updateUser,
A.UPDATE_TIME updateTime,
t2.inside_prod_id insideProdId,
t2.PBC_CODE pbcCode,
A.PBC_ACCOUNT_ID pbcAccountIdShow,
B.ACCOUNT_ID accountId
from PBC_PRD_ACCOUNT_END_SUB A
LEFT JOIN (select DISTINCT PBC_ACCOUNT_ID,ACCOUNT_ID from PBC_PRD_ACCOUNT_SUB) B ON A.PBC_ACCOUNT_ID = B.PBC_ACCOUNT_ID
LEFT JOIN(
SELECT
inside_prod_id,
pbc_code
FROM
pbc_prod_assetpool_code
WHERE
status='E'
AND code_type='02'
)t2 ON t2.inside_prod_id=B.ACCOUNT_ID



            #{items,jdbcType=VARCHAR}




            #{items,jdbcType=VARCHAR}




        AND B.ACCOUNT_ID IN

            #{item,jdbcType=VARCHAR}




        and A.STATUS in

            #{item,jdbcType=VARCHAR}



        and trim(A.REGIST_SEQNO) in

            #{item,jdbcType=VARCHAR}



        and A.SEND_STATUS in

            #{item,jdbcType=VARCHAR}



        and A.SUBMIT_FEEDBACK_STATUS in

            #{item,jdbcType=VARCHAR}



        and DATE_FORMAT(A.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart}


        and DATE_FORMAT(A.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd}


        and DATE_FORMAT(A.SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart}


        and DATE_FORMAT(A.SUBMIT_TIME,'%Y-%m-%d') <= #{submitTimeEnd}


        and DATE_FORMAT(A.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{pbcSubmitDeadlineDateStart}


        and DATE_FORMAT(A.PBC_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{pbcSubmitDeadlineDateEnd}


        and DATE_FORMAT(A.MDATE,'%Y-%m-%d') >= #{mdateStart}


        and DATE_FORMAT(A.MDATE,'%Y-%m-%d') <= #{mdateEnd}


        and DATE_FORMAT(A.UPDATE_TIME,'%Y-%m-%d') = #{updateTime}



        and DATE_FORMAT(A.MDATE,'%Y-%m-%d') >= #{startDate}


        and DATE_FORMAT(A.MDATE,'%Y-%m-%d') <= #{endDate}



        and t2.INSIDE_PROD_ID = #{insideProdId}



ORDER BY A.PBC_SUBMIT_DEADLINE ASC, A.UPDATE_TIME DESC

mapper.insert:
insert into PBC_PRD_ACCOUNT_END_SUB_HIS () select REGIST_SEQNO, PBC_ACCOUNT_ID, MDATE, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from PBC_PRD_ACCOUNT_END_SUB where PBC_ACCOUNT_ID in
#{item.pbcAccountId,jdbcType=CHAR}
and SEND_STATUS in ('02','03')

insert into PBC_PRD_ACCOUNT_END_SUB () select HIS_NO, PBC_ACCOUNT_ID, MDATE, SEND_STATUS, SUBMIT_TIME, SUBMIT_FEEDBACK_STATUS, SUMIT_SEQ, STATUS_DATE, PBC_SUBMIT_DEADLINE, SUBMIT_DEADLINE, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, NOW(), UPDATE_USER, NOW() from ( select , rank() over (partition by PBC_ACCOUNT_ID order by ifnull(update_time,create_time) desc) ranknum from PBC_PRD_ACCOUNT_END_SUB_HIS where PBC_ACCOUNT_ID in
#{item.pbcAccountId,jdbcType=CHAR}
)as tt where tt.ranknum = 1

mapper.delete:
delete from PBC_PRD_ACCOUNT_END_SUB_HIS
where PBC_ACCOUNT_ID in (
select  PBC_ACCOUNT_ID
from (
select PBC_ACCOUNT_ID ,
rank() over (partition by PBC_ACCOUNT_ID  order by ifnull(update_time,create_time) desc) ranknum
from PBC_PRD_ACCOUNT_END_SUB_HIS
where
PBC_ACCOUNT_ID in

    #{item.pbcAccountId,jdbcType=CHAR}

)as tt
where tt.ranknum= 1
)

mapper.select:
select count(1) from CHB_PRD_POSITION
where DATE_FORMAT(cdate,'%Y-%m-%d') = DATE_FORMAT(#{dto.mdate,jdbcType=DATE},'%Y-%m-%d')
and prod_id = #{dto.prodId,jdbcType=VARCHAR}

     	select  SUM(ifnull(BALANCE.B_AMT,0)) from bok_balance BALANCE
			where BOOKSET_ID=#{prodid,jdbcType=VARCHAR}
			and BALANCE_DATE=(
				select max(BALANCE_DATE) from bok_balance
				where BOOKSET_ID=#{prodid,jdbcType=VARCHAR}
				and BALANCE_DATE >=#{cdate,jdbcType=DATE}
				)
			and SUBJECT_LEVEL='1'
			AND subject_no='1002'
